    _validate_compare_minimum_profiles_result(result)
)

n_pairs = len(scales) - 1
n_minimums = len(minimums)
n_thresholds = len(thresholds)

data_rows: list[dict] = []
for minimum_index, minimum in enumerate(minimums):
    abs_sums = [0.0 for _threshold in thresholds]
    peak = 0.0
    intervals: list[dict] = []
    for pair_index, (left, right) in enumerate(zip(scales, scales[1:])):
        change_row = changes[pair_index * n_minimums + minimum_index]
        pair_rates = change_row["rates"]
        magnitude = 0.0
        for threshold_index, rate in enumerate(pair_rates):
            magnitude = max(magnitude, abs(rate))
            abs_sums[threshold_index] += abs(rate)
        peak = max(peak, magnitude)
        if magnitude > tolerance:
            rounded_magnitude = _round_output(float(magnitude))
            if not _is_finite(rounded_magnitude):
                raise ValueError("derived statistics must be finite")
            intervals.append(
                {
                    "left": left,
                    "right": right,
                    "magnitude": rounded_magnitude,
                }
            )

    mean_abs = []
    for abs_sum in abs_sums:
        mean = _round_output(float(abs_sum) / n_pairs)
        if not _is_finite(mean):
            raise ValueError("derived statistics must be finite")
        mean_abs.append(mean)

    rounded_peak = _round_output(float(peak))
    if not _is_finite(rounded_peak):
        raise ValueError("derived statistics must be finite")

    data_rows.append(
        {
            "minimum": minimum,
            "count": n_pairs,
            "mean_abs": mean_abs,
            "peak": rounded_peak,
            "intervals": intervals,
        }
    )

rounded_tolerance = _round_output(float(tolerance))
if not _is_finite(rounded_tolerance):
    raise ValueError("derived statistics must be finite")

return {
    "schema": _PROFILE_DIAGNOSTIC_SCHEMA,
    "tolerance": rounded_tolerance,
    "scales": list(scales),
    "minimums": list(minimums),
    "thresholds": list(thresholds),
    "panels": list(result["panels"]),
    "data": data_rows,
}

